 959	\begin{lemma}[Formalization support for coefficient polynomial agreement]
 960		\label{lem:coefficient-polynomial-agreement}
 961		\lean{MIPStarRE.QPBT.evalCoefficient_collision_card_le}
 962		\lean{MIPStarRE.QPBT.linePolynomialOfCoefficients_eq_ofFn,
 963			MIPStarRE.QPBT.linePolynomialOfCoefficients_eval,
 964			MIPStarRE.QPBT.linePolynomialOfCoefficients_injective,
 965			MIPStarRE.QPBT.linePolynomialOfCoefficients_natDegree_le}
 966		\leanok
 967		Let $K$ be a finite integral domain, let $c\in\N$, and let
 968		$f,g\in K^{c+1}$ be distinct coefficient vectors. Their polynomials
 969		$p_f(T)=\sum_{i=0}^{c}f_iT^i$ and $p_g(T)=\sum_{i=0}^{c}g_iT^i$
 970		agree at at most $c$ elements of $K$.
 971		The coefficient representation is injective, preserves evaluation,
 972		and has natural degree at most $c$.
 973		This is a formalization-only auxiliary for the Schwartz--Zippel step
 974		in the proof of Lemma~\ref{lem:qld-xz-lines}
 975		(\texttt{14\_analysis\_of\_the\_pauli\_basis\_test.tex:955}).
 976		There is no restriction $c<|K|$.
 977	\end{lemma}
 978	\begin{proof}
 979		\leanok
 980		The coefficient representation is injective, preserves evaluation,
 981		and gives polynomials of degree at most $c$. If the polynomials agreed
 982		at more than $c$ elements, the univariate root bound applied to their
 983		difference would force them to be equal, contradicting $f\ne g$.
 984	\end{proof}
